#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    // best[k]: largest value from exactly k chosen digits of the prefix (-1 = impossible)
    long long best[4] = {0, -1, -1, -1};
    for (int i = 0; i < n; i++) {
        long long d;
        cin >> d;
        for (int k = 3; k >= 1; k--) // descending so each digit is used once
            if (best[k - 1] >= 0) best[k] = max(best[k], best[k - 1] * 10 + d);
    }
    cout << max({best[1], best[2], best[3]}) << "\n";
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        // best[k]: largest value from exactly k chosen digits of the prefix (-1 = impossible)
        long[] best = {0, -1, -1, -1};
        for (int i = 0; i < n; i++) {
            long d = in.nextLong();
            for (int k = 3; k >= 1; k--) // descending so each digit is used once
                if (best[k - 1] >= 0) best[k] = Math.max(best[k], best[k - 1] * 10 + d);
        }
        System.out.println(Math.max(best[1], Math.max(best[2], best[3])));
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(r, &n)
	// best[k]: largest value from exactly k chosen digits of the prefix (-1 = impossible)
	best := [4]int64{0, -1, -1, -1}
	for i := 0; i < n; i++ {
		var d int64
		fmt.Fscan(r, &d)
		for k := 3; k >= 1; k-- { // descending so each digit is used once
			if best[k-1] >= 0 {
				best[k] = max(best[k], best[k-1]*10+d)
			}
		}
	}
	fmt.Println(max(best[1], best[2], best[3]))
}
